#!/usr/bin/env bash
# Generated by install.sh.
EXECUTABLE="__EXECUTABLE__"
if [[ ! -x "$EXECUTABLE" ]]; then
    echo "pappardelle: $EXECUTABLE is missing or not executable. Run install.sh again to rebuild it:" >&2
    echo "  ./install.sh from your clone, or" >&2
    echo "  curl -fsSL https://raw.githubusercontent.com/chardigio/pappardelle/main/install.sh | bash" >&2
    exit 1
fi
exec "$EXECUTABLE" "$@"
